float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
float fbm(vec2 p){float a=0.5,s=0.0;for(int i=0;i<5;i++){s+=a*n(p);p*=2.03;a*=0.5;}return s;}
void mainImage(out vec4 o, in vec2 f){vec2 uv=f/iResolution.xy; vec2 b=vec2(uv.x*16.0, uv.y*48.0); float row=floor(b.y); b.x+=mod(row,2.0)*0.5; vec2 id=floor(b); vec2 g=fract(b); float mort=step(0.06,g.x)*step(g.x,0.97)*step(0.1,g.y)*step(g.y,0.92); float v=h(id); vec3 brick=mix(vec3(0.30,0.12,0.08),vec3(0.46,0.20,0.12),v)*(0.75+0.5*fbm(f*0.02)); brick*=0.85+0.3*n(f*0.15); vec3 mortar=vec3(0.22,0.20,0.18)*(0.8+0.4*n(f*0.3)); vec3 c=mix(mortar,brick,mort); float grime=smoothstep(0.0,0.6,1.0-uv.y)*0.0+fbm(uv*vec2(3.0,1.0)*6.0)*0.6; c*=1.0-0.55*grime*smoothstep(0.2,1.0,fbm(vec2(uv.x*20.0,uv.y*2.0))); o=vec4(c,1.0);}
